question.en:
What is the output of the following code snippet?
```cpp
double amount = 5;
std::cout << amount / 2 << " " << 5 / 2 << std::endl;
```

example.code:
#include <iostream>
#include <cmath>

int main()
{
    double annualInterestRate = 0.0;
    int numberOfYears = 0;
    double loanAmount = 0.0;

    if (std::cin >> annualInterestRate >> numberOfYears >> loanAmount)
    {
        // Step 2: Convert annual rate in percent to monthly rate in decimal
        double monthlyInterestRate = annualInterestRate / 1200.0;

        // Step 3: Compute monthly payment
        double monthlyPayment = (loanAmount * monthlyInterestRate) /
            (1.0 - 1.0 / std::pow(1.0 + monthlyInterestRate, numberOfYears * 12));

        // Step 4: Compute total payment
        double totalPayment = monthlyPayment * numberOfYears * 12;

        // Truncate to two decimal places using explicit casting
        double displayMonthly = static_cast<int>(monthlyPayment * 100) / 100.0;
        double displayTotal = static_cast<int>(totalPayment * 100) / 100.0;

        // Step 5: Display results
        std::cout << "Monthly payment: " << displayMonthly << std::endl;
        std::cout << "Total payment: " << displayTotal << std::endl;
    }
    return 0;
}
